'use client';import {useEffect,useState} from 'react';export default function Page(){const[s,setS]=useState('confirming');useEffect(()=>{const id=new URLSearchParams(window.location.search).get('session_id');if(!id)return;const poll=()=>fetch(`/api/checkout-status?session_id=${encodeURIComponent(id)}`).then(r=>r.json()).then(x=>setS(x.status));poll();const t=setInterval(poll,2000);return()=>clearInterval(t)},[]);return <main><h1>{s==='order_created'?'Order confirmed':'Payment received'}</h1><p>{s==='order_created'?'Your Shopify order has been created.':'We are confirming your order.'}</p></main>}
